function Logo({ inverse = false, small = false }: { inverse?: boolean; small?: boolean }) {
  const size = small ? "w-36" : "w-40 sm:w-44";
  const imageClass = cn("h-10 object-cover object-center transition-opacity duration-300", size);
  if (inverse) return <Link href="/" className="inline-flex items-center" aria-label="Nómada Race, inicio">
    <img src="/nomada-race-wordmark-night.png" alt="Nómada Race" className={cn(imageClass, "hover:opacity-80")} />
  </Link>;

  return <Link href="/" className="inline-flex items-center" aria-label="Nómada Race, inicio">
    <img src="/nomada-race-wordmark-day.png" alt="Nómada Race" className={cn(imageClass, "dark:hidden hover:opacity-75")} />
    <img src="/nomada-race-wordmark-night.png" alt="Nómada Race" className={cn(imageClass, "hidden dark:block hover:opacity-75")} />
  </Link>;
}

function ThemeToggle({ compact = false }: { compact?: boolean }) {
  const [dark, setDark] = useState(false);

  useEffect(() => {
    const match = document.cookie.match(/(?:^|; )nomada-theme=([^;]+)/);
    const stored = match ? decodeURIComponent(match[1]) : window.localStorage.getItem("nomada-theme");
    const nextDark = stored ? stored === "dark" : window.matchMedia("(prefers-color-scheme: dark)").matches;
    const root = document.documentElement;
    root.classList.toggle("dark", nextDark);
    root.dataset.theme = nextDark ? "dark" : "light";
    root.style.colorScheme = nextDark ? "dark" : "light";
    setDark(nextDark);
  }, []);

  const toggleTheme = () => {
    const nextDark = !document.documentElement.classList.contains("dark");
    const theme = nextDark ? "dark" : "light";
    const root = document.documentElement;
    root.classList.toggle("dark", nextDark);
    root.dataset.theme = theme;
    root.style.colorScheme = theme;
    window.localStorage.setItem("nomada-theme", theme);
    document.cookie = `nomada-theme=${theme}; path=/; max-age=31536000; SameSite=Lax`;
    setDark(nextDark);
  };

  return <button type="button" onClick={toggleTheme} aria-pressed={dark} aria-label={dark ? "Cambiar a modo día" : "Cambiar a modo noche"} title={dark ? "Cambiar a modo día" : "Cambiar a modo noche"} className={cn("theme-toggle group inline-flex items-center justify-center rounded-full border border-zinc-200 bg-white/70 font-bold text-zinc-600 shadow-sm transition-[transform,background-color,border-color,box-shadow] duration-300 hover:-translate-y-px hover:border-brand-neon hover:text-brand-neon hover:shadow-md active:scale-[.97]", compact ? "h-10 w-10" : "h-10 gap-2 px-3")}>
    <span className="grid h-6 w-6 place-items-center rounded-full bg-zinc-950 text-white transition-transform duration-500 group-hover:rotate-[18deg]">{dark ? <Sun className="h-3.5 w-3.5" /> : <Moon className="h-3.5 w-3.5" />}</span>
    {!compact && <span className="hidden text-xs xl:inline">{dark ? "Modo día" : "Modo noche"}</span>}
  </button>;
}

function StatusPill({ status }: { status: EventStatus | string }) {
  const style = status === "Fotos listas" ? "bg-emerald-100 text-emerald-800" : status === "Preventa" ? "bg-orange-100 text-orange-800" : status === "Pagado" || status === "Activo" || status === "Activa" || status === "Completado" ? "bg-emerald-100 text-emerald-800" : status === "Pendiente" || status === "Procesando" ? "bg-amber-100 text-amber-800" : status === "Reembolsado" || status === "Error" ? "bg-rose-100 text-rose-800" : "bg-zinc-100 text-zinc-600";
  return <span className={cn("inline-flex w-fit items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-extrabold", style)}><span className="h-1.5 w-1.5 rounded-full bg-current" />{status}</span>;
}

